{
  "title": "LOD & Occlusion Culling Pipeline Controls",
  "width": 920,
  "height": 150,
  "controls": [
    {
      "type": "select",
      "label": "Hidden-Stud Occlusion (re-run C)",
      "bind": "lod_cull_hidden",
      "default": 1,
      "options": [
        {
          "label": "Enabled (Cull Studs Under Bricks)",
          "value": 1
        },
        {
          "label": "Disabled (Render Every Stud)",
          "value": 0
        }
      ],
      "x": 12,
      "y": 42,
      "width": 260,
      "height": 64
    },
    {
      "type": "slider",
      "label": "LOD Distance Bias (re-run C)",
      "bind": "lod_dist_scale",
      "default": 1,
      "min": 0.4,
      "max": 2,
      "step": 0.1,
      "precision": 1,
      "x": 286,
      "y": 42,
      "width": 210,
      "height": 64
    },
    {
      "type": "select",
      "label": "3D Shader Mode (Live)",
      "bind": "lod_debug_color",
      "default": 0,
      "options": [
        {
          "label": "0 · True ABS Plastic Colours",
          "value": 0
        },
        {
          "label": "1 · LOD Heatmap (Green=LOD0, Amber=LOD1, Blue=LOD2)",
          "value": 1
        }
      ],
      "x": 510,
      "y": 42,
      "width": 240,
      "height": 64
    },
    {
      "type": "select",
      "label": "Mesh Wireframe (Live)",
      "bind": "lod_wireframe",
      "default": 0,
      "options": [
        {
          "label": "Solid Shaded",
          "value": 0
        },
        {
          "label": "Wireframe Triangles",
          "value": 1
        }
      ],
      "x": 764,
      "y": 42,
      "width": 144,
      "height": 64
    }
  ]
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <nb.h>

#define GX 20
#define GZ 20
#define GY 14

/* Triangle budgets per primitive */
#define TRIS_BRICK_BODY 12
#define TRIS_STUD_LOD0  48
#define TRIS_STUD_LOD1  18
#define TRIS_STUD_LOD2   0

static int occ[GY][GZ][GX];

struct CityBrick {
  int x, y, z;
  int sx, sz;
  int color;
  int lod;          /* 0 = High, 1 = Med, 2 = Far (stud-less) */
  int exposed_mask; /* bitmask of which (dx,dz) studs on top are visible */
};

static struct CityBrick bricks[1024];
static int n_bricks = 0;

void place_brick(int x, int y, int z, int sx, int sz, int color) {
  if (x < 0 || z < 0 || y < 0 || x + sx > GX || z + sz > GZ || y >= GY) return;
  for (int dz = 0; dz < sz; dz++)
    for (int dx = 0; dx < sx; dx++)
      if (occ[y][z + dz][x + dx]) return;

  for (int dz = 0; dz < sz; dz++)
    for (int dx = 0; dx < sx; dx++)
      occ[y][z + dz][x + dx] = color;

  bricks[n_bricks++] = (struct CityBrick){ x, y, z, sx, sz, color, 0, 0 };
}

int main(void) {
  int cull_hidden = (int)nb_get_int("lod_cull_hidden", 1);
  double dist_scale = nb_get_number("lod_dist_scale", 1.0);

  memset(occ, 0, sizeof occ);
  n_bricks = 0;

  /* 1. Paved Sidewalk & Road Baseplate (y = 0) */
  for (int z = 0; z < GZ; z += 2) {
    for (int x = 0; x < GX; x += 4) {
      int is_road = (z >= 12 && z <= 17);
      int col = is_road ? 6 : 5;
      if (is_road && z == 14 && (x % 8 == 0)) col = 7; /* White crosswalk stripe */
      place_brick(x, 0, z, 4, 2, col);
    }
  }

  /* 2. Building A: Red Corner Café (x = 1..8, z = 1..8, y = 1..8) */
  for (int y = 1; y <= 8; y++) {
    int wall_col = (y == 1 || y == 5 || y == 8) ? 7 : 1;
    for (int x = 1; x <= 5; x += 4) {
      place_brick(x, y, 1, 4, 1, wall_col);
      if (!(y >= 2 && y <= 3 && x == 5)) /* Café front doorway */
        place_brick(x, y, 8, 4, 1, (y % 2 == 0) ? 8 : wall_col);
    }
    for (int z = 2; z <= 5; z += 3) {
      place_brick(1, y, z, 1, 3, wall_col);
      place_brick(8, y, z, 1, 3, (y % 2 == 0) ? 8 : wall_col);
    }
  }
  /* Café Roof & Awning */
  for (int z = 1; z <= 7; z += 2)
    for (int x = 1; x <= 5; x += 4)
      place_brick(x, 9, z, 4, 2, 6);
  place_brick(3, 3, 9, 4, 1, 2); /* Yellow awning */
  place_brick(3, 3, 9, 4, 1, 1);

  /* 3. Building B: Blue Townhouse & Clocktower (x = 11..18, z = 1..9, y = 1..12) */
  for (int y = 1; y <= 11; y++) {
    int col = (y >= 9) ? 2 : (y % 3 == 0) ? 7 : 4;
    place_brick(11, y, 1, 4, 2, col);
    place_brick(15, y, 1, 4, 2, col);
    place_brick(11, y, 7, 4, 2, col);
    place_brick(15, y, 7, 4, 2, col);
    place_brick(11, y, 3, 2, 4, col);
    place_brick(17, y, 3, 2, 4, col);
  }
  place_brick(13, 12, 3, 4, 4, 1); /* Red spire cap */

  /* 4. Streetlight & Plaza Fountain (front sidewalk z = 10..11, 18..19) */
  for (int y = 1; y <= 5; y++) place_brick(2, y, 11, 1, 1, y == 5 ? 2 : 6);
  for (int y = 1; y <= 5; y++) place_brick(17, y, 11, 1, 1, y == 5 ? 2 : 6);
  place_brick(8, 1, 18, 4, 2, 5);
  place_brick(9, 2, 18, 2, 2, 4);

  /* Camera focal reference point near the front-right street corner */
  double cam_x = 18.0, cam_y = 6.0, cam_z = 20.0;

  int total_studs = 0;
  int visible_studs = 0;
  int lod_studs[3] = {0, 0, 0};

  for (int i = 0; i < n_bricks; i++) {
    double bx = bricks[i].x + bricks[i].sx * 0.5;
    double by = bricks[i].y + 0.5;
    double bz = bricks[i].z + bricks[i].sz * 0.5;
    double dist = sqrt((bx - cam_x)*(bx - cam_x) + (by - cam_y)*(by - cam_y) + (bz - cam_z)*(bz - cam_z));
    double scaled_d = dist / (dist_scale > 0.1 ? dist_scale : 1.0);

    if (scaled_d < 12.5) bricks[i].lod = 0;
    else if (scaled_d < 20.0) bricks[i].lod = 1;
    else bricks[i].lod = 2;

    int mask = 0;
    int bit = 0;
    for (int dz = 0; dz < bricks[i].sz; dz++) {
      for (int dx = 0; dx < bricks[i].sx; dx++) {
        total_studs++;
        int covered = (bricks[i].y + 1 < GY) && (occ[bricks[i].y + 1][bricks[i].z + dz][bricks[i].x + dx] > 0);
        if (!cull_hidden || !covered) {
          mask |= (1 << bit);
          visible_studs++;
          lod_studs[bricks[i].lod]++;
        }
        bit++;
      }
    }
    bricks[i].exposed_mask = mask;
  }

  int body_tris = n_bricks * TRIS_BRICK_BODY;
  int naive_tris = body_tris + total_studs * TRIS_STUD_LOD0;
  int culled_tris = body_tris + visible_studs * TRIS_STUD_LOD0;
  int lod_tris = body_tris
               + lod_studs[0] * TRIS_STUD_LOD0
               + lod_studs[1] * TRIS_STUD_LOD1
               + lod_studs[2] * TRIS_STUD_LOD2;

  double savings_pct = naive_tris > 0 ? 100.0 * (1.0 - (double)lod_tris / naive_tris) : 0.0;

  printf("=== LDraw Geometry Kernel & Instanced LOD Report ===\n");
  printf("City Block Bricks: %d | Total Stud Sites: %d | Exposed Studs: %d (%.1f%% occluded)\n",
         n_bricks, total_studs, visible_studs,
         total_studs > 0 ? 100.0 * (total_studs - visible_studs) / total_studs : 0.0);
  printf("Stud LOD Split:    LOD0 (16-gon): %d | LOD1 (6-gon): %d | LOD2 (Culled): %d\n\n",
         lod_studs[0], lod_studs[1], lod_studs[2]);

  printf("%-32s %12s %12s\n", "Pipeline Stage", "Triangles", "Reduction");
  printf("------------------------------------------------------------\n");
  printf("%-32s %12d %11.1f%%\n", "1. Naive Unculled (All LOD0)", naive_tris, 0.0);
  printf("%-32s %12d %11.1f%%\n", "2. + Hidden-Stud Occlusion",   culled_tris,
         100.0 * (1.0 - (double)culled_tris / naive_tris));
  printf("%-32s %12d %11.1f%%\n", "3. + Distance Stud LOD (0/1/2)", lod_tris, savings_pct);
  printf("%-32s %12d %11.1f%%\n", "4. Brick Bodies Only (Floor)", body_tris,
         100.0 * (1.0 - (double)body_tris / naive_tris));

  static char json[65536];
  int pos = 0;
  pos += snprintf(json + pos, sizeof(json) - pos,
    "{\"brickCount\":%d,\"totalStuds\":%d,\"visibleStuds\":%d,"
    "\"lod0Studs\":%d,\"lod1Studs\":%d,\"lod2Studs\":%d,"
    "\"naiveTris\":%d,\"culledTris\":%d,\"lodTris\":%d,\"bodyTris\":%d,"
    "\"savingsPct\":%.1f,\"bricks\":[",
    n_bricks, total_studs, visible_studs,
    lod_studs[0], lod_studs[1], lod_studs[2],
    naive_tris, culled_tris, lod_tris, body_tris, savings_pct);

  for (int i = 0; i < n_bricks; i++) {
    pos += snprintf(json + pos, sizeof(json) - pos,
      "%s[%d,%d,%d,%d,%d,%d,%d,%d]",
      i ? "," : "",
      bricks[i].x, bricks[i].y, bricks[i].z,
      bricks[i].sx, bricks[i].sz, bricks[i].color,
      bricks[i].lod, bricks[i].exposed_mask);
  }
  pos += snprintf(json + pos, sizeof(json) - pos, "]}");
  nb_set_json("lod_scene", json);
  return 0;
}

// Visualize the GPU Triangle Budget across the 4 C geometry-kernel stages
const s = nb.get('lod_scene');
if (!s) return 'Run the C cell above to compute LOD metrics.';

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  title: `GPU Triangle Budget by C Geometry Pass (${s.savingsPct}% Total Reduction)`,
  width: 680,
  height: 190,
  data: {
    values: [
      { stage: '1. Naive (All Studs LOD0)', tris: s.naiveTris, color: '#ef4444' },
      { stage: '2. + Hidden-Stud Culling', tris: s.culledTris, color: '#f59e0b' },
      { stage: '3. + Distance Stud LOD', tris: s.lodTris, color: '#10b981' },
      { stage: '4. Brick Bodies Only', tris: s.bodyTris, color: '#3b82f6' },
    ],
  },
  mark: { type: 'bar', cornerRadiusEnd: 5 },
  encoding: {
    y: { field: 'stage', type: 'nominal', sort: null, title: null },
    x: { field: 'tris', type: 'quantitative', title: 'Total GPU Triangles Submitted' },
    color: { field: 'color', type: 'nominal', scale: null, legend: null },
    tooltip: [
      { field: 'stage', title: 'Pipeline Stage' },
      { field: 'tris', title: 'Triangles', format: ',' },
    ],
  },
};

// The triangle bill at every LOD distance bias, from the bricks the C cell shared.
const scene = nb.get('lod_scene');
if (!scene) return 'Run the C cell first.';
const BODY = 12, LOD0 = 48, LOD1 = 18;            // triangles, as in the C cell
const VIEW = [18, 6, 20];                          // the C cell's viewpoint
const current = Number(nb.get('lod_dist_scale') ?? 1);

const bitsSet = (mask) => { let n = 0; for (; mask; mask >>= 1) n += mask & 1; return n; };
const bricks = scene.bricks.map(([x, y, z, sx, sz, , , mask]) => ({
  dist: Math.hypot(x + sx / 2 - VIEW[0], y + 0.5 - VIEW[1], z + sz / 2 - VIEW[2]),
  studs: bitsSet(mask),
}));

function bill(bias) {
  let close = 0, middle = 0;
  for (const b of bricks) {
    const d = b.dist / bias;
    if (d < 12.5) close += b.studs;
    else if (d < 20) middle += b.studs;
  }
  return { body: bricks.length * BODY, close: close * LOD0, middle: middle * LOD1 };
}
const total = (t) => t.body + t.close + t.middle;

const rows = [];
for (let i = 4; i <= 20; i++) {
  const t = bill(i / 10);
  rows.push({ bias: i / 10, part: 'brick bodies', triangles: t.body });
  rows.push({ bias: i / 10, part: 'close studs (16 sides)', triangles: t.close });
  rows.push({ bias: i / 10, part: 'middle studs (6 sides)', triangles: t.middle });
}
for (const b of [0.4, current, 2]) console.log(`bias ${b.toFixed(1)}: ${total(bill(b)).toLocaleString('en-GB')} triangles`);
console.log('matches the C cell at the current bias:', total(bill(current)) === scene.lodTris);

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 260,
  title: 'Triangles drawn at each LOD distance bias',
  data: { values: rows },
  encoding: { x: { field: 'bias', type: 'quantitative', title: 'distance bias', scale: { zero: false } } },
  layer: [
    {
      mark: { type: 'area', tooltip: true },
      encoding: {
        y: { field: 'triangles', type: 'quantitative', stack: true, title: 'triangles' },
        color: {
          field: 'part', type: 'nominal', title: null,
          scale: { domain: ['brick bodies', 'middle studs (6 sides)', 'close studs (16 sides)'], range: ['#3b82f6', '#f59e0b', '#10b981'] },
        },
        order: { field: 'part', sort: 'ascending' },
      },
    },
    { mark: { type: 'rule', color: '#ef4444', strokeDash: [6, 4] }, encoding: { x: { datum: current } } },
  ],
};
